draw:
const omega = Math.sqrt(p.k / p.mass);
const wallX = 26, eqX = W * 0.34, scale = W * 0.16, midY = H * 0.34;
const x = p.amplitude * Math.cos(omega * t);
const massX = eqX + x * scale;

// wall
ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 6, midY - 38, 6, 76);

// spring
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
for (let i = 1; i <= 12; i++) {
  const sxp = wallX + (massX - 16 - wallX) * i / 12;
  const syp = midY + (i % 2 === 0 ? -10 : 10) * (i === 12 ? 0 : 1);
  ctx.lineTo(sxp, syp);
}
ctx.lineTo(massX - 16, midY);
ctx.stroke();

// equilibrium marker
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(eqX, midY - 44); ctx.lineTo(eqX, midY + 44); ctx.stroke();
ctx.setLineDash([]);

// mass
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(massX - 16, midY - 16, 32, 32, 4); ctx.fill();

// x(t) trace
const gy = H * 0.8;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(16, gy); ctx.lineTo(W - 16, gy); ctx.stroke();
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
for (let i = 0; i < 240; i++) {
  const tt = t - (240 - i) * 0.016;
  const px2 = W - 16 - (240 - i) * 1.3;
  const py2 = gy - p.amplitude * Math.cos(omega * tt) * 26;
  i === 0 ? ctx.moveTo(px2, py2) : ctx.lineTo(px2, py2);
}
ctx.stroke();

out.note = "T = " + (2 * Math.PI / omega).toFixed(2) + " s, omega = " + omega.toFixed(2) + " rad/s";
